import React, { useState } from 'react';
import { MapPin, ChevronRight, ChevronLeft, Search, Box, Layers, Globe } from 'lucide-react';

const AreasZonesTab = () => {
  const [viewLevel, setViewLevel] = useState('ZONES'); 
  const [selectedZone, setSelectedZone] = useState(null);
  const [selectedArea, setSelectedArea] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  const zoneData = [
    {
      id: 'Z-1', name: 'NORTH_SECTOR', code: 'NS-ALPHA', count: 3, 
      color: '#FF5B03', bg: '#FFB6A9',
      areas: [
        { id: 'A-1', name: 'Hillside Drive', location: 'North Ridge', code: 'HSD-44', bins: ['BN-401', 'BN-405', 'BN-409'] },
        { id: 'A-2', name: 'University Road', location: 'East Campus', code: 'URD-12', bins: ['BN-502', 'BN-503'] }
      ]
    },
    {
      id: 'Z-2', name: 'CENTRAL_HUB', code: 'CH-BRAVO', count: 1, 
      color: '#47510B', bg: '#CAD23C',
      areas: [
        { id: 'A-3', name: 'Main Square', location: 'Downtown', code: 'MSQ-01', bins: ['BN-101', 'BN-102'] }
      ]
    }
  ];

  const filteredData = viewLevel === 'ZONES' 
    ? zoneData.filter(z => z.name.includes(searchQuery.toUpperCase()))
    : selectedZone?.areas.filter(a => a.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div className="w-full h-full animate-slot flex flex-col gap-6 p-2 md:p-6 overflow-hidden">

      {/* 🟢 TOP NAV: SOFT GHOST BAR */}
      <div className="flex flex-col md:flex-row items-center justify-between gap-4 bg-[#A1AED1]/10 p-6 rounded-[40px] backdrop-blur-md border border-white/20">
        <div className="flex items-center gap-5">
          {viewLevel !== 'ZONES' && (
            <button 
              onClick={() => setViewLevel(viewLevel === 'BINS' ? 'AREAS' : 'ZONES')} 
              className="w-12 h-12 flex items-center justify-center bg-[#AB1717] text-white rounded-full hover:scale-110 transition-transform shadow-lg"
            >
              <ChevronLeft size={24} strokeWidth={3} />
            </button>
          )}
          <div>
            <h2 className="text-3xl font-black text-[#47510B] tracking-tight lowercase italic">
              {viewLevel === 'ZONES' ? 'sectors' : viewLevel === 'AREAS' ? selectedZone.name : selectedArea.name}
            </h2>
            <div className="flex gap-2 mt-1">
              <div className="h-2 w-8 rounded-full bg-[#FF5B03]" />
              <div className="h-2 w-2 rounded-full bg-[#CAD23C]" />
            </div>
          </div>
        </div>

        <div className="relative w-full md:w-96">
          <Search className="absolute left-4 top-3.5 text-[#47510B]/40" size={18} />
          <input 
            type="text" placeholder="type to filter..." 
            className="w-full bg-[#FDFAD8] border-none rounded-[30px] py-3.5 pl-12 pr-6 text-sm font-bold text-[#47510B] shadow-inner focus:ring-4 focus:ring-[#FFB6A9]/50 transition-all outline-none"
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* 🟠 MAIN VIEWPORT: AUTOMATIC SIZING */}
      <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar">

        {/* LEVEL 1: ZONES (Soft Bubbles) */}
        {viewLevel === 'ZONES' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredData.map(zone => (
              <div 
                key={zone.id} 
                onClick={() => {setSelectedZone(zone); setViewLevel('AREAS');}}
                style={{ backgroundColor: zone.bg }}
                className="group p-8 rounded-[60px] cursor-pointer hover:rotate-2 hover:scale-[1.02] transition-all duration-500 shadow-xl border-b-[12px] border-[#47510B]/20"
              >
                <div className="flex justify-between items-start mb-10">
                  <div className="bg-white/40 p-4 rounded-[30px] backdrop-blur-md">
                    <Globe size={32} style={{ color: zone.color }} />
                  </div>
                  <span className="bg-[#47510B] text-white text-[10px] font-black px-4 py-1.5 rounded-full uppercase tracking-widest">{zone.code}</span>
                </div>
                <h3 className="text-4xl font-black text-[#47510B] tracking-tighter leading-none mb-2">{zone.name}</h3>
                <p className="text-sm font-bold text-[#47510B]/60 italic">{zone.areas.length} locations active</p>
              </div>
            ))}
          </div>
        )}

        {/* LEVEL 2: AREAS (Smooth Pill Tracks) */}
        {viewLevel === 'AREAS' && (
          <div className="flex flex-col gap-4 max-w-5xl mx-auto">
            {filteredData.map(area => (
              <div 
                key={area.id} 
                onClick={() => {setSelectedArea(area); setViewLevel('BINS');}}
                className="group flex flex-col md:flex-row items-center bg-white p-4 rounded-[40px] hover:bg-[#FFF24D] transition-all cursor-pointer border-4 border-transparent hover:border-[#47510B] shadow-md"
              >
                <div className="w-16 h-16 rounded-full bg-[#A1AED1]/20 flex items-center justify-center text-[#AB1717] group-hover:bg-[#AB1717] group-hover:text-white transition-colors">
                  <MapPin size={24} strokeWidth={3} />
                </div>
                <div className="md:ml-8 flex-grow text-center md:text-left mt-4 md:mt-0">
                  <h4 className="text-2xl font-black text-[#47510B] uppercase tracking-tight">{area.name}</h4>
                  <p className="text-xs font-bold text-[#A1AED1] uppercase tracking-[0.2em]">{area.location} • {area.code}</p>
                </div>
                <div className="mt-4 md:mt-0 px-8 py-3 bg-[#FDFAD8] rounded-full text-lg font-black text-[#47510B] group-hover:bg-[#47510B] group-hover:text-white transition-all shadow-sm">
                  {area.bins.length} units
                </div>
              </div>
            ))}
          </div>
        )}

        {/* LEVEL 3: BINS (Glowing Nodes) */}
        {viewLevel === 'BINS' && (
          <div className="flex flex-wrap justify-center gap-8 py-10">
            {selectedArea.bins.map(binId => (
              <div key={binId} className="w-32 h-32 md:w-40 md:h-40 bg-[#47510B] rounded-[50px] flex flex-col items-center justify-center gap-3 relative group hover:shadow-[0_0_40px_rgba(202,210,60,0.5)] hover:-translate-y-4 transition-all duration-500">
                <div className="absolute -top-2 -right-2 w-10 h-10 bg-[#FF5B03] rounded-full flex items-center justify-center border-4 border-white text-white">
                  <Box size={16} />
                </div>
                <span className="text-[#CAD23C] font-black text-xl tracking-tighter">{binId}</span>
                <div className="w-8 h-1 bg-[#CAD23C]/30 rounded-full" />
              </div>
            ))}
          </div>
        )}

      </div>

      {/* 🟡 FOOTER: MINI INDICATOR */}
      <div className="flex justify-center p-4">
        <div className="flex gap-4 p-2 bg-[#47510B] rounded-full border-4 border-white shadow-lg">
          <div className={`w-3 h-3 rounded-full ${viewLevel === 'ZONES' ? 'bg-[#FF5B03]' : 'bg-white/20'}`} />
          <div className={`w-3 h-3 rounded-full ${viewLevel === 'AREAS' ? 'bg-[#CAD23C]' : 'bg-white/20'}`} />
          <div className={`w-3 h-3 rounded-full ${viewLevel === 'BINS' ? 'bg-[#FFB6A9]' : 'bg-white/20'}`} />
        </div>
      </div>

    </div>
  );
};

export default AreasZonesTab;
